import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Canonical Term Arrows","description":"","frontmatter":{"title":"Canonical Term Arrows","type":"adr","date":"2026-09-14T00:00:00.000Z","status":"proposed","status_note":"Accepted — the canonical form is `Term`; no function/call/block/assign/object nodes."},"headers":[],"relativePath":"handl/project/adrs/0100-canonical-term-arrows.md","filePath":"vendored/handl/project/adrs/0100-canonical-term-arrows.md"}'),a={name:`handl/project/adrs/0100-canonical-term-arrows.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0100-canonical-term-arrows" tabindex="-1">ADR-0100: Canonical Term Arrows <a class="header-anchor" href="#adr-0100-canonical-term-arrows" aria-label="Permalink to “ADR-0100: Canonical Term Arrows”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>The canonical internal form is the arrow-calculus <code>Term</code></strong> — no <code>function</code>, <code>call</code>, <code>block</code>, <code>assign</code> or <code>object</code> nodes.</li><li><strong>The constructor set is fixed</strong>: <code>Arr</code>, <code>Const</code>, <code>Op</code>, <code>Seq</code>, <code>First</code>, <code>Second</code>, <code>Choice</code>, <code>Loop</code>, <code>App</code>, <code>Handle</code>.</li><li><strong><code>x ~&gt; body</code> lowers point-free</strong> using <code>arr</code> and the product combinators; a body that is not point-free expressible lifts to a pure <code>FunctionValue</code> wrapped in <code>Arr</code>.</li><li><strong>Calls lower to <code>App</code></strong> when the callee is dynamic and to <code>Seq</code> when it is a known arrow; <code>do</code> and <code>=</code> lower to <code>Seq</code> and are not semantic nodes.</li><li><strong>Records, operators and literals lower to <code>Op</code>/<code>Arr</code>/<code>Const</code></strong>; there are no object or operator nodes.</li><li><strong>The engine interprets <code>Term</code> directly</strong>; <code>eval.yaml</code> describes how each constructor is interpreted.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The AST had a node per surface convenience (function, call, block, assign, object), so every engine re-implemented their semantics. Lowering to <code>Term</code> gives one graph and one interpretation table; sugar disappears at the boundary.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep surface nodes in the canonical form</strong> — they are sugar.</li><li><strong>A second evaluator per node kind</strong> — one <code>Term</code> interpreter.</li><li><strong>Keep <code>=</code> as a semantic node</strong> — it is threading through <code>Seq</code>.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>One canonical graph; engines interpret constructors, not syntax.</li><li>Non-point-free bodies cost a <code>FunctionValue</code> lift.</li><li><code>eval.yaml</code> becomes the interpretation table.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — <code>Term</code> constructors and the interpreter.</li><li><code>crates/handl-kit-data-canonical/data/eval.yaml</code> — constructor schemes.</li><li>Lowering tests (surface → <code>Term</code>).</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The constructor list, lowering rules and the engine switch: +<a href="./../design/0100-canonical-term-arrows.html"><code>design/0100-canonical-term-arrows.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};